// features/lifecycle.feature: A page past the last vendor is empty but still reports the total
import { expect, expectStatus, test, uniqueName } from "../../fixtures";

test("a page past the last vendor is empty but still reports the total", { tag: "@LIF-15" }, async ({ apiAs, factory }) => {
  // Arrange: vendors under a unique name tag, so parallel tests can't change the total
  const tag = uniqueName("Paging").replace(/\s+/g, "-");
  await factory.vendor({ name: `${tag} Alpha` });
  await factory.vendor({ name: `${tag} Beta` });
  const member = await apiAs("member");
  const firstPage = await expectStatus<{ items: unknown[]; total: number }>(
    await member.get("/api/vendors", { params: { q: tag, limit: 20, offset: 0 } }),
    200,
  );
  expect(firstPage.total, "both arranged vendors are counted").toBe(2);

  // Act
  const response = await member.get("/api/vendors", { params: { q: tag, limit: 20, offset: firstPage.total + 10 } });

  // Assert
  const beyond = await expectStatus<{ items: unknown[]; total: number; offset: number }>(response, 200);
  expect(beyond.items).toEqual([]);
  expect(beyond.total).toBe(firstPage.total);
});
